import json, sys
raw = json.loads(sys.stdin.read())
inner = json.loads(raw['result'])
exps = inner['data']['experiments']
for eid, exp in exps.items():
    metrics = exp.get('metrics',{}) or {}
    spec = exp.get('spec',{}) or {}
    combined = json.dumps(metrics) + json.dumps(spec)
    if 'bootstrap' in combined.lower() or 'resample' in combined.lower() or 'n_bootstrap' in combined.lower():
        # Extract bootstrap count
        print(f'=== {eid} ===')
        for key in ['bootstrap_ci', 'bootstrap_ci_10k', 'bootstrap_1v2_95CI']:
            if key in metrics:
                print(f'  {key}: present')
        # Check for n_bootstrap in spec
        if 'n_bootstrap' in combined.lower() or 'bootstrap' in json.dumps(spec).lower():
            print(f'  spec mentions bootstrap')
        # Look for specific counts
        if '10000' in combined or '10k' in combined.lower() or '10K' in combined:
            print(f'  → 10K bootstrap detected')
        if '1000' in combined and '10000' not in combined:
            print(f'  → 1K bootstrap detected')
        print()
